try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    IntStream.range(0, 10_000).forEach(i -> {
        executor.submit(() -> {
            var res = httpClient.send(request(i), BodyHandlers.ofString());
            log.info("resp " + i + " " + res.statusCode());
            return null;
        });
    });
}

